for name,edits in changes.items():
 p=r/name
 s=p.read_text()
 for before,after in edits:
  assert s.count(before)==1, name+": source no longer matches reviewed update"
  s=s.replace(before,after,1)
 p.write_text(s)
for name in ['api.js','app.js']:(r/'dist'/name).write_text((r/'site'/name).read_text())
(r/'test/non-referral-admin.test.mjs').write_text("import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport {initialState,engine,execute,scoped,buildingAccess,users} from '../server/engine.mjs';\ntest('Efrain retains administrator access while excluded from referral staff even with an older saved roster',()=>{\n const state=JSON.parse(JSON.stringify(initialState(false)));delete state.users.find(u=>u.id==='u4').handlesReferrals;\n const tl=engine(state,'u4');assert.equal(tl.isAdmin(),true);\n assert.equal(buildingAccess(state,'u4'),'all');\n assert.equal(users.find(u=>u.id==='u4').authType,'private_link');\n assert.equal(scoped(state,'u4').users.find(u=>u.id==='u4').handlesReferrals,false);\n assert.ok(!tl.referralStaff().some(u=>u.id==='u4'));\n assert.ok(tl.referralStaff().some(u=>u.id==='u1'));\n});\ntest('non-referral admin cannot be selected as owner; admin can still create a lead for a marketer',()=>{\n let state=initialState(false),data={first:'Fictional',last:'Ownership',building:'hallmark',payer:'Private pay',rep:'u4'};\n assert.throws(()=>execute(state,'u0',{op:'createLead',createdId:'L_nonreferral',args:[data]}),/handles referrals/);\n assert.throws(()=>execute(state,'u4',{op:'createLead',createdId:'L_nonreferral',args:[{...data,rep:null}]}),/handles referrals/);\n state=execute(state,'u4',{op:'createLead',createdId:'L_nonreferral',args:[{...data,rep:'u3'}]});\n assert.equal(state.leads[0].rep,'u3');assert.equal(state.leads[0].createdBy,'u4');\n assert.throws(()=>execute(state,'u0',{op:'assign',expectedVersion:1,args:['L_nonreferral',{rep:'u4'}]}),/handles referrals/);\n});\n")
